  max-width: 1200px;
  margin: 0 auto;
}
#globalWrapper .section-padding {
  padding: 60px 0;
}
#globalWrapper .flex-center {
  justify-content: center;
  align-items: center;
  display: flex;
}
#globalWrapper .btn-primary {
  background-color: var(--edu-yellow);
  color: var(--text-dark);
  border-radius: 8px;
  justify-content: center;
  align-items: center;
  padding: 12px 24px;
  font-weight: 700;
  transition: all 0.2s;
  display: inline-flex;
}
#globalWrapper .btn-primary:hover {
  background-color: var(--edu-yellow-hover);
  box-shadow: var(--shadow-md);
  transform: translateY(-2px);
}
#globalWrapper .tag {
  color: #997f00;
  background-color: rgba(255, 212, 0, 0.2);
  border-radius: 4px;
  padding: 4px 8px;
  font-size: 0.75rem;
  font-weight: 700;
  display: inline-block;
}
#globalWrapper .header-container {
  background-color: var(--bg-white);
  z-index: 1000;
  border-bottom: 1px solid var(--border-color);
  width: 100%;
  transition: box-shadow 0.3s;
  position: relative;
}
#globalWrapper .header-container.sticky {
  box-shadow: 0 2px 16px rgba(0, 0, 0, 0.0588235294);
}
#globalWrapper .header-top {
  color: var(--text-muted);
  border-bottom: 1px solid var(--border-color);
  letter-spacing: 0;
  background-color: #fcfcfe;
  padding: 7px 0;
  font-size: 0.75rem;
}
#globalWrapper .flex-between {
  justify-content: space-between;
  align-items: center;
  display: flex;
}
#globalWrapper .cert-mark {
  color: var(--text-base);
  font-weight: 700;
}
#globalWrapper .util-menu {
  align-items: center;
  gap: 4px;
  display: flex;
  position: relative;
}
#globalWrapper .util-menu a {
  color: var(--text-muted);
  border-radius: 4px;
  padding: 4px 10px;
  font-weight: 500;
  transition: all 0.15s;
}
#globalWrapper .util-menu a:hover {
  color: var(--text-dark);
  background-color: var(--bg-gray);
}
#globalWrapper {
  /* 로그인 레이어 컨테이너 */
}
#globalWrapper .util-menu .item.login {
  position: relative;
  display: inline-block;
}
#globalWrapper {
  /* 이름 및 화살표 스타일 */
}
#globalWrapper .util-menu .item.login > a {
  display: inline-flex;
  align-items: center;
  color: var(--text-muted);
  font-weight: 500;
  text-decoration: none;
  padding: 4px 10px;
}
#globalWrapper .util-menu .item.login > a:hover {
  color: var(--text-dark);
  background-color: var(--bg-gray);
}
#globalWrapper {
  /* 화살표 아이콘 회전 애니메이션 */
}
#globalWrapper .util-menu .item.login .arrow-icon {
  transition: transform 0.2s ease;
}
#globalWrapper .util-menu .item.login.active .arrow-icon {
  transform: rotate(180deg);
}
#globalWrapper {
  /* 레이어 팝업 스타일 */
}
#globalWrapper .util-menu .item.login .header-layer {
  position: absolute;
  top: 100%;
  left: 50%;
  transform: translateX(-50%);
  margin-top: 8px;
  z-index: 110;
  display: none;
  border: 1px solid #e9e9e9;
  background-color: #fff;
  box-shadow: 0 10px 25px rgba(0, 0, 0, 0.08), 0 2px 8px rgba(0, 0, 0, 0.04);
  border-radius: 6px;
  width: 120px;
  box-sizing: border-box;
  padding: 6px 0;
}
#globalWrapper {
  /* 마우스가 이름에서 드롭다운으로 넘어갈 때 사이 간격을 메우는 투명 영역 */
}
#globalWrapper .util-menu .item.login .header-layer::before {
  content: "";
  position: absolute;
  top: -10px;
  left: 0;
  width: 100%;
  height: 10px;
  background-color: transparent;
}
#globalWrapper {
  /* 활성화 시 노출 */
}
#globalWrapper .util-menu .item.login.active .header-layer {
  display: block;
}
#globalWrapper {
  /* 드롭다운 메뉴 리스트 스타일 */
}
#globalWrapper .util-menu .item.login .menu-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
}
#globalWrapper .util-menu .item.login .menu-list .menu {
  width: 100%;
  padding: 0 4px;
  box-sizing: border-box;
}
#globalWrapper .util-menu .item.login .menu-list .menu a {
  display: block;
  width: 100%;
  padding: 5px 12px;
  font-size: 11.5px;
  color: #444;
  text-align: left;
  text-decoration: none;
  border-radius: 4px;
  font-weight: 500;
  box-sizing: border-box;
  transition: background-color 0.2s, color 0.2s;
}
#globalWrapper .util-menu .item.login .menu-list .menu a:hover {
  background-color: #f1f3f5;
  color: var(--text-dark, #111) !important;
}
#globalWrapper .header-main {
  height: 85px;
  position: relative;
}
#globalWrapper .gnb-layout {
  align-items: center;
  display: flex;
}
#globalWrapper .gnb-left {
  flex: 1;
  align-items: center;
  gap: 4px;
  display: flex;
}
#globalWrapper .gnb-center {
  z-index: 2;
  position: absolute;
  left: 50%;
  transform: translate(-50%);
}
#globalWrapper .gnb-right {
  flex: 1;
  justify-content: flex-end;
  align-items: center;
  gap: 12px;
  display: flex;
}
#globalWrapper .logo-area {
  align-items: center;
  gap: 36px;
  display: flex;
}
#globalWrapper .logo {
  letter-spacing: -2px;
  font-size: 32px;
  font-weight: 900;
}
#globalWrapper .text-yellow {
  color: var(--edu-yellow);
}
#globalWrapper .gnb {
  gap: 4px;
  display: flex;
}
#globalWrapper .gnb a {
  color: var(--text-muted);
  letter-spacing: -0.2px;
  border-radius: 6px;
  padding: 6px 10px;
  font-size: 1rem;
  font-weight: 700;
  transition: all 0.2s;
  position: relative;
}
#globalWrapper .gnb a:hover {
  color: var(--text-dark);
  background-color: var(--bg-gray);
}
#globalWrapper .gnb a.active {
  color: var(--text-dark);
}
#globalWrapper .gnb a.active:after {
  content: "";
  background: #ffd400;
  border-radius: 2px;
  height: 2.5px;
  position: absolute;
  bottom: -23px;
  left: 10px;
  right: 10px;
  box-shadow: 0 0 8px rgba(255, 212, 0, 0.8), 0 0 16px rgba(255, 212, 0, 0.4);
}
#globalWrapper .search-area {
  align-items: center;
  gap: 12px;
  display: flex;
}
#globalWrapper .search-expand-wrap {
  cursor: pointer;
  border-radius: 20px;
  align-items: center;
  gap: 0;
  padding: 8px;
  transition: background 0.2s;
  display: flex;
}
#globalWrapper .search-expand-wrap:hover {
  background: var(--bg-gray);
}
#globalWrapper .search-icon-static {
  color: var(--text-muted);
  flex-shrink: 0;
  transition: color 0.2s;
}
#globalWrapper .search-expand-wrap:hover .search-icon-static {
  color: var(--text-dark);
}
#globalWrapper .search-field-expand {
  align-items: center;
  width: 0;
  transition: width 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  display: flex;
  overflow: hidden;
}
#globalWrapper .search-expand-wrap:hover .search-field-expand {
  width: 150px;
  padding-left: 6px;
}
#globalWrapper .search-field-expand input {
  width: 100%;
  color: var(--text-base);
  cursor: pointer;
  caret-color: rgba(0, 0, 0, 0);
  background: 0 0;
  border: none;
  outline: none;
  font-size: 0.875rem;
}
#globalWrapper .fake-cursor {
  background: var(--text-dark);
  opacity: 0;
  border-radius: 1px;
  flex-shrink: 0;
  width: 1.5px;
  height: 14px;
  transition: opacity 0.15s 0.3s;
  animation: 1s step-end infinite cursorBlink;
}
#globalWrapper .search-expand-wrap:hover .fake-cursor {
  opacity: 1;
}
@keyframes cursorBlink {
  0%, to {
    opacity: 1;
  }
  50% {
    opacity: 0;
  }
}
#globalWrapper .my-classroom {
  color: var(--text-muted);
  white-space: nowrap;
  border-radius: 6px;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 0.2s;
  display: flex;
}
#globalWrapper .my-classroom:hover {
  color: var(--text-dark);
  background-color: var(--bg-gray);
}
#globalWrapper .gnb-icon-btn {
  color: var(--text-muted);
  cursor: pointer;
  background: 0 0;
  border: none;
  border-radius: 6px;
  align-items: center;
  gap: 6px;
  padding: 6px 8px;
  font-size: 0.875rem;
  font-weight: 600;
  transition: all 0.2s;
  display: flex;
}
#globalWrapper .gnb-icon-btn:hover {
  color: var(--text-dark);
  background-color: var(--bg-gray);
}
#globalWrapper .noti-bell {
  width: 40px;
  height: 40px;
  color: var(--text-muted);
  border-radius: 50%;
  justify-content: center;
  align-items: center;
  transition: all 0.2s;
  display: flex;
  position: relative;
}
#globalWrapper .noti-bell:hover {
  background-color: var(--bg-gray);
  color: var(--text-dark);
}
#globalWrapper .badge-count {
  color: #fff;
  background-color: #ef4444;
  border: 2px solid #fff;
  border-radius: 50%;
  justify-content: center;
  align-items: center;
  width: 15px;
  height: 15px;
  font-size: 0.6rem;
  font-weight: 800;
  display: flex;
  position: absolute;
  top: 4px;
  right: 4px;
}
#globalWrapper .search-box input {
  color: var(--text-dark);
  background: 0 0;
  border: none;
  outline: none;
  flex: 1;
  min-width: 0;
  font-family: inherit;
  font-size: 0.875rem;
}
#globalWrapper .search-box input::-moz-placeholder {
