}
#globalWrapper .search-box input::placeholder {
  color: var(--text-light);
}
#globalWrapper .search-box button {
  color: var(--text-muted);
  align-items: center;
  transition: color 0.15s;
  display: flex;
}
#globalWrapper .search-box:focus-within .search-box button {
  color: var(--text-dark);
}
#globalWrapper .menu-btn {
  color: var(--text-dark);
  cursor: pointer;
  background: 0 0;
  border: none;
  border-radius: 50%;
  justify-content: center;
  align-items: center;
  width: 40px;
  height: 40px;
  transition: all 0.2s;
  display: flex;
}
#globalWrapper .menu-btn:hover {
  background-color: var(--bg-gray);
}
#globalWrapper .menu-btn.active {
  background: var(--text-dark);
  color: #fff;
}
#globalWrapper .btn-header-evidence {
  color: #666;
  cursor: pointer;
  background: 0 0;
  border: none;
  padding: 0;
  font-size: 0.75rem;
  font-weight: 500;
  text-decoration: underline;
}
#globalWrapper .btn-header-evidence:hover {
