}
#globalWrapper .header-evidence-overlay {
  z-index: 10001;
  background-color: rgba(0, 0, 0, 0.6);
  justify-content: center;
  align-items: center;
  padding: 20px;
  display: flex;
  position: fixed;
  inset: 0;
}
#globalWrapper .header-evidence-modal {
  background-color: #fff;
  border-radius: 12px;
  flex-direction: column;
