}
#globalWrapper .search-result-body .container {
  padding: 48px 0;
}
#globalWrapper .search-result-group {
  margin-bottom: 32px;
  padding-bottom: 32px;
}
#globalWrapper .search-result-group.border-top {
  border-top: 1px solid #eee;
  margin-bottom: 0;
  padding-top: 40px;
}
#globalWrapper .result-group-title.cert-mark {
  color: #868e96;
  font-size: 0.8rem;
  font-weight: 500;
}
#globalWrapper .cert-sweep-link {
