}
#globalWrapper .shiny-sweep-text {
  color: rgba(0, 0, 0, 0);
  background: linear-gradient(110deg, #f59e0b 35%, #fff 50%, #f59e0b 65%) 0 0/200%;
  -webkit-background-clip: text;
  background-clip: text;
  font-weight: 800;
  animation: 2.5s cubic-bezier(0.4, 0, 0.2, 1) infinite shineSweepText;
  display: inline-block;
}
@keyframes shineSweepText {
