  align-items: center;
  gap: 16px;
  display: flex;
}
#globalWrapper .noti-date {
  color: #aaa;
  font-size: 13px;
}
#globalWrapper .noti-close-btn {
  color: #ccc;
  cursor: pointer;
  background: 0 0;
  border: none;
  padding: 0;
  display: flex;
}
#globalWrapper .noti-close-btn:hover {
  color: #666;
}
#globalWrapper .hero-infinity-section {
  width: 100vw;
  max-width: 100%;
  padding-top: 16px;
  position: relative;
  overflow: hidden;
  /* 기존 인피니티 히어로 스타일이 외부 영역에 침범하지 않도록 내부로 완전히 격리시킵니다. */
}
#globalWrapper .hero-infinity-section .carousel-viewport {
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 360px;
  display: flex;
  position: relative;
}
#globalWrapper .hero-infinity-section .carousel-track {
  justify-content: center;
  width: 860px;
  height: 100%;
  display: flex;
  position: relative;
}
#globalWrapper .hero-infinity-section .slide {
  cursor: pointer;
  border-radius: 20px;
  width: 100%;
  height: 100%;
  padding: 40px 50px;
  transition: all 0.6s cubic-bezier(0.25, 1, 0.5, 1);
  position: absolute;
  top: 0;
}
#globalWrapper .hero-infinity-section .slide-active {
  opacity: 1;
  z-index: 10;
  cursor: default;
  transform: translate(0) scale(1);
}
#globalWrapper .hero-infinity-section .slide-prev {
  opacity: 0.4;
  z-index: 5;
  transform: translate(-92%) scale(0.88);
}
#globalWrapper .hero-infinity-section .slide-next {
  opacity: 0.4;
  z-index: 5;
  transform: translate(92%) scale(0.88);
}
#globalWrapper .hero-infinity-section .slide-hidden {
  opacity: 0;
  z-index: -1;
  pointer-events: none;
  transform: translate(0) scale(0.8);
}
#globalWrapper .hero-infinity-section .slide-prev:hover,
#globalWrapper .hero-infinity-section .slide-next:hover {
  opacity: 0.7;
}
#globalWrapper .hero-infinity-section .slide-inner {
  text-align: center;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
  cursor: pointer;
}
#globalWrapper .hero-infinity-section .slide-text-area {
  z-index: 2;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  max-width: 640px;
  display: flex;
}
#globalWrapper .hero-infinity-section .slide-tag {
  border-radius: 20px;
  margin-bottom: 16px;
  padding: 6px 16px;
  font-size: 0.85rem;
  font-weight: 800;
  display: inline-block;
}
#globalWrapper .hero-infinity-section .slide-title {
  white-space: pre-line;
  letter-spacing: -1.5px;
  text-align: center;
  color: inherit;
  margin-bottom: 24px;
  font-size: 2.4rem;
  font-weight: 700;
  line-height: 1.35;
}
#globalWrapper .hero-infinity-section .highlight-text {
  display: block;
  color: inherit;
  letter-spacing: -0.5px;
  font-weight: 900;
}
#globalWrapper .hero-infinity-section .slide-subtitle {
  opacity: 0.8;
  text-align: center;
  margin-bottom: 28px;
  font-size: 1.05rem;
  font-weight: 500;
}
#globalWrapper .hero-infinity-section .slide-btn {
  color: #fff;
  backdrop-filter: blur(8px);
  background-color: rgba(255, 255, 255, 0.1490196078);
  border: 1px solid rgba(255, 255, 255, 0.4);
  border-radius: 30px;
  padding: 12px 28px;
  font-size: 1rem;
  font-weight: 700;
  transition: all 0.2s;
  position: relative;
  overflow: hidden;
  transform: translateY(5px);
  box-shadow: 0 4px 15px rgba(0, 0, 0, 0.1019607843);
}
#globalWrapper .hero-infinity-section .slide-btn:after {
  content: "";
  background: linear-gradient(90deg, rgba(255, 255, 255, 0) 0%, rgba(255, 255, 255, 0.4) 50%, rgba(255, 255, 255, 0) 100%);
  width: 50%;
  height: 100%;
  animation: 3s cubic-bezier(0.16, 1, 0.3, 1) infinite btnShine;
  position: absolute;
  top: 0;
  left: -100%;
  transform: skew(-20deg);
}
#globalWrapper .hero-infinity-section .slide-btn:hover {
  color: #111;
  background-color: #fff;
}
#globalWrapper .hero-infinity-section .slide-brand-center {
  text-align: center;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  width: 100%;
  height: 100%;
  display: flex;
