  /* 미세한 데이터 파티클 상승 (Floating Particles) */
  /* ========================================= */
}
#globalWrapper .particles-layer {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  z-index: 1;
  /* 배경보단 위, 텍스트보단 아래 */
  pointer-events: none;
  opacity: 1;
  transition: opacity 0.8s ease;
}
#globalWrapper {
  /* 축소 상태에서는 불티 효과를 더욱 은은하게(opacity: 0.3) 처리 */
}
#globalWrapper .brand-banner-wrapper.intro-shrinking .particles-layer,
#globalWrapper .brand-banner-wrapper.intro-finished .particles-layer {
  opacity: 0.25;
}
#globalWrapper .particle {
  position: absolute;
  bottom: -10px;
  background-color: #FFD400;
  border-radius: 50%;
  opacity: 0;
  animation: floatUp linear infinite;
  box-shadow: 0 0 12px 2px rgb(255, 212, 0);
}
#globalWrapper {
  /* 무작위 크기 및 떨어지는 위치 설정을 위한 다중 딜레이 처리 */
}
#globalWrapper .particle:nth-child(3n+1) {
  width: 5px;
  height: 5px;
  animation-duration: 2.5s;
  opacity: 1;
}
#globalWrapper .particle:nth-child(3n+2) {
  width: 6px;
  height: 6px;
  animation-duration: 3s;
  opacity: 0.9;
}
#globalWrapper .particle:nth-child(3n) {
  width: 4px;
  height: 4px;
  animation-duration: 2s;
  opacity: 1;
}
