#globalWrapper {
  /* ========================================= */
  /* 상시 반짝이는 트윙클 플레어 (Twinkle Flares) */
  /* ========================================= */
}
#globalWrapper .banner-flares {
  position: absolute;
  inset: 0;
  z-index: 1;
  /* 배경보단 위, 텍스트보단 아래 */
  pointer-events: none;
  overflow: hidden;
}
#globalWrapper .flare-dot {
  position: absolute;
  width: 3px;
  height: 3px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 6px 2px rgba(255, 212, 0, 0.95), 0 0 12px 4px rgba(255, 212, 0, 0.45);
  opacity: 0;
  animation: flareTwinkle 3.2s ease-in-out infinite;
}
#globalWrapper {
  /* 십자 광선 (가로/세로) */
}
#globalWrapper .flare-dot::before,
#globalWrapper .flare-dot::after {
  content: "";
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
}
#globalWrapper .flare-dot::before {
  width: 26px;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(255, 212, 0, 0.85), transparent);
}
#globalWrapper .flare-dot::after {
  width: 1px;
  height: 26px;
  background: linear-gradient(0deg, transparent, rgba(255, 212, 0, 0.85), transparent);
}
@keyframes flareTwinkle {
  0%, 100% {
    opacity: 0;
    transform: scale(0.3);
  }
  50% {
    opacity: 1;
    transform: scale(1);
  }
}
@keyframes floatUp {
  0% {
    transform: translateY(0) translateX(0);
    opacity: 0;
  }
  20% {
    opacity: 1;
  }
  80% {
    opacity: 1;
  }
  100% {
    transform: translateY(-160px) translateX(20px);
    opacity: 0;
  }
}
#globalWrapper {
  /* ========================================= */
  /* 십자 빛 교차 (Cross/Lens Flare) 이펙트 (확대 배너 전용) */
  /* ========================================= */
}
#globalWrapper .cross-flare-effect {
  position: absolute;
  top: 50%;
  left: 58%;
  width: 0;
  height: 0;
  z-index: 1;
  pointer-events: none;
  opacity: 0;
  animation: flareReveal 0.8s ease-out 0.2s forwards;
}
#globalWrapper .brand-banner-wrapper.intro-shrinking .cross-flare-effect,
#globalWrapper .brand-banner-wrapper.intro-finished .cross-flare-effect {
  opacity: 0 !important;
  transition: opacity 0.8s ease;
}
@keyframes flareReveal {
  0% {
    opacity: 0;
    transform: scale(0.6);
  }
  100% {
    opacity: 1;
    transform: scale(1);
  }
}
#globalWrapper .flare-line {
  position: absolute;
  background: #fff;
}
#globalWrapper .flare-line.horizontal {
  top: 50%;
  left: -50vw;
  width: 100vw;
  height: 2px;
  transform: translateY(-50%);
  background: linear-gradient(90deg, transparent 0%, rgba(255, 255, 255, 0.6) 40%, rgb(255, 255, 255) 50%, rgba(255, 255, 255, 0.6) 60%, transparent 100%);
}
#globalWrapper .flare-line.vertical {
  left: 50%;
  top: -75px;
  width: 2px;
  height: 150px;
  transform: translateX(-50%);
  background: linear-gradient(0deg, transparent, rgb(255, 212, 0), #fff, rgb(255, 212, 0), transparent);
}
#globalWrapper .flare-core {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
  height: 8px;
  background-color: #fff;
  border-radius: 50%;
  box-shadow: 0 0 10px 4px rgba(255, 255, 255, 0.9), 0 0 40px 15px rgba(255, 212, 0, 0.4);
}
#globalWrapper .flare-halo {
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 400px;
  height: 400px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 212, 0, 0.15) 0%, transparent 65%);
  filter: blur(15px);
}
#globalWrapper {
  /* ========================================= */
  /* 숫자 강조 반짝이 별 (Twinkle Star) 이펙트 (축소 배너 전용) */
  /* ========================================= */
}
#globalWrapper .twinkle-star {
  position: absolute;
  top: -10px;
  /* 숫자 텍스트 우측 상단 가장자리로 배치 */
  right: -25px;
  width: 50px;
  height: 50px;
  pointer-events: none;
  z-index: 2;
  /* 기본(확대) 상태에서는 숨김 */
  opacity: 0;
  transform: scale(0.5);
  transition: opacity 0.6s ease, transform 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275);
}
#globalWrapper {
  /* 띠배너 상태(축소 모드)로 전환 시, 십자 빛은 fade out / 별은 화려하게 등장 */
}
